	x = [ 2.0, -3.0, -5.0, 7.0, 6.0 ];
	expected = [ -5.0, -3.0, 2.0, 7.0, 6.0 ];
	gpartitionqs( 3, 1, -1.0, toAccessorArray( x ), -2 );
